INSERT INTO public.ai_prompt_rules (escopo, conteudo, ordem, ativo, observacao)
VALUES
('global', 'CONFIRMAÇÃO DE NOVO DESTINO — FORMATO EXATO EM 2 BALÕES: nunca inicie busca de novo destino sem confirmar TAMBÉM a quantidade de passageiros, mesmo que já tenha sido dita antes. Balão 1 confirma origem + pax: "Claro! Para Porto Seguro, continua saindo de Vitória e seriam as mesmas 2 pessoas?". Balão 2 coleta período + duração de forma conversada: "Vocês têm alguma data específica em mente para a viagem? E mais ou menos quantas noites gostariam de ficar? Se estiverem flexíveis, posso procurar o período com melhor custo-benefício.". PROIBIDO empilhar alternativas na mesma frase ("data ou período e quantas noites, ou posso buscar...") — isso vira formulário. A flexibilidade entra como complemento no final, nunca como "ou, ou, ou".', 25, true, 'Auditoria: Porto Seguro 21:24');